+  <title>Support Contact Form</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      background: #090b12;
+      color: #f8fafc;
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      min-height: 100vh;
+      margin: 0;
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+      background:
+        radial-gradient(circle at top left, rgba(56, 189, 248, 0.18), transparent 34rem),
+        radial-gradient(circle at bottom right, rgba(168, 85, 247, 0.18), transparent 30rem),
+        #090b12;
+    }
+
+    .support-page {
+      width: min(100%, 560px);
+    }
+
+    .contact-card {
+      position: relative;
+      overflow: hidden;
+      padding: 36px;
+      border: 1px solid rgba(148, 163, 184, 0.22);
+      border-radius: 28px;
+      background: linear-gradient(145deg, rgba(15, 23, 42, 0.94), rgba(17, 24, 39, 0.82));
+      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
+      backdrop-filter: blur(20px);
+    }
+
+    .contact-card::before {
+      content: "";
+      position: absolute;
+      inset: 0;
+      pointer-events: none;
+      background: linear-gradient(135deg, rgba(255, 255, 255, 0.1), transparent 28%);
+    }
+
+    .card-content {
+      position: relative;
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: #38bdf8;
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.13em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 6vw, 3rem);
+      line-height: 1;
+      letter-spacing: -0.05em;
+    }
+
+    .intro {
+      margin: 16px 0 28px;
+      color: #cbd5e1;
+      line-height: 1.65;
+    }
+
+    .form-field {
+      margin-bottom: 20px;
+    }
+
+    label {
+      display: flex;
+      justify-content: space-between;
+      gap: 12px;
+      margin-bottom: 8px;
+      color: #e2e8f0;
+      font-size: 0.94rem;
+      font-weight: 650;
+    }
+
+    .optional {
+      color: #94a3b8;
+      font-size: 0.82rem;
+      font-weight: 500;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid rgba(148, 163, 184, 0.28);
+      border-radius: 16px;
+      outline: none;
+      padding: 15px 16px;
+      background: rgba(15, 23, 42, 0.74);
+      color: #f8fafc;
+      font: inherit;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    input::placeholder {
+      color: #64748b;
+    }
+
+    input:focus {
+      border-color: #38bdf8;
+      background: rgba(15, 23, 42, 0.96);
+      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.14);
+    }
+
+    input:user-invalid {
+      border-color: #fb7185;
+    }
+
+    .helper-text {
+      margin: 8px 2px 0;
+      color: #94a3b8;
+      font-size: 0.86rem;
+      line-height: 1.45;
+    }
+
+    .submit-button {
+      width: 100%;
+      margin-top: 8px;
+      border: 0;
+      border-radius: 16px;
+      padding: 16px 20px;
+      background: linear-gradient(135deg, #38bdf8, #818cf8);
+      color: #020617;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      box-shadow: 0 16px 36px rgba(56, 189, 248, 0.28);
+      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      filter: brightness(1.05);
+      box-shadow: 0 18px 44px rgba(56, 189, 248, 0.34);
+    }
+
+    .submit-button:active {
+      transform: translateY(0);
+    }
+
+    @media (max-width: 520px) {
+      .contact-card {
+        padding: 28px 20px;
+        border-radius: 24px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="root"></main>
+
+  <script>
+    const fields = [
+      {
+        id: "full-name",
+        label: "Full name",
+        name: "fullName",
+        type: "text",
+        placeholder: "Jordan Taylor",
+        autocomplete: "name",
+        required: true
+      },
+      {
+        id: "email-address",
+        label: "Email address",
+        name: "email",
+        type: "email",
+        placeholder: "jordan@example.com",
+        autocomplete: "email",
+        required: true
+      },
+      {
+        id: "phone-number",
+        label: "Phone number",
+        name: "phone",
+        type: "tel",
+        placeholder: "+1 (555) 123-4567",
+        autocomplete: "tel",
+        required: false,
+        helperText: "Use international or local format, including area code when applicable."
+      }
+    ];
+
+    function escapeHtml(value) {
+      return String(value).replace(/[&<>"']/g, (character) => ({
+        "&": "&amp;",
+        "<": "&lt;",
+        ">": "&gt;",
+        '"': "&quot;",
+        "'": "&#39;"
+      }[character]));
+    }
+
+    function FormField(field) {
+      const optionalText = field.required ? "" : '<span class="optional">Optional</span>';
+      const helper = field.helperText
+        ? `<p class="helper-text" id="${field.id}-helper">${escapeHtml(field.helperText)}</p>`
+        : "";
+      const describedBy = field.helperText ? ` aria-describedby="${field.id}-helper"` : "";
+
+      return `
+        <div class="form-field">
+          <label for="${field.id}">
+            <span>${escapeHtml(field.label)}</span>
+            ${optionalText}
+          </label>
+          <input
+            id="${field.id}"
+            name="${field.name}"
+            type="${field.type}"
+            placeholder="${escapeHtml(field.placeholder)}"
+            autocomplete="${field.autocomplete}"
+            ${field.required ? "required" : ""}
+            ${describedBy}
+          >
+          ${helper}
+        </div>
+      `;
+    }
+
+    function ContactForm() {
+      return `
+        <form class="contact-form" action="#" method="post" novalidate>
+          ${fields.map(FormField).join("")}
+          <button class="submit-button" type="submit">Contact support</button>
+        </form>
+      `;
+    }
+
+    function SupportPage() {
+      return `
+        <section class="support-page" aria-labelledby="support-title">
+          <div class="contact-card">
+            <div class="card-content">
+              <p class="eyebrow">Support request</p>
+              <h1 id="support-title">How can we help?</h1>
+              <p class="intro">
+                Send our team your contact details and we will get back to you with the next best step.
+              </p>
+              ${ContactForm()}
+            </div>
+          </div>
+        </section>
+      `;
+    }
+
+    document.getElementById("root").innerHTML = SupportPage();
+  </script>
+</body>
+</html>
*** End Patch
