      position: relative;
      overflow: hidden;
      padding: 36px;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 28px;
      background: linear-gradient(145deg, rgba(15, 23, 42, 0.94), rgba(17, 24, 39, 0.82));
      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
      backdrop-filter: blur(20px);
    }

